'use strict';
const path = require('path');
const fs = require('fs-extra');
const archiver = require('archiver');
const { exec } = require('child_process');
const { promisify } = require('util');
const execAsync = promisify(exec);

const TEMPLATE_DIR = path.join(__dirname, '..', 'templates', 'android');

// ─── createProject ────────────────────────────────────────────────────────────
/**
 * Creates a complete Android project in BUILDS_DIR/<buildId>/project/
 * then packages it as project.zip.
 *
 * @param {string} buildId
 * @param {object} config
 * @param {string|null} webDir  – directory containing web files to bundle
 * @param {string} buildsDir
 * @returns {string} projectDir
 */
async function createProject(buildId, config, webDir, buildsDir) {
  const buildDir  = path.join(buildsDir, buildId);
  const projectDir = path.join(buildDir, 'project');

  await fs.ensureDir(buildDir);
  // Copy template
  await fs.copy(TEMPLATE_DIR, projectDir, { overwrite: true });

  // Build the Java source directory based on package name
  const pkgParts = config.packageName.split('.');
  const javaDir  = path.join(projectDir, 'app', 'src', 'main', 'java', ...pkgParts);
  await fs.ensureDir(javaDir);

  // Generate source files from templates
  await generateSources(projectDir, javaDir, config);

  // Copy web content
  if (config.loadType === 'local' && webDir) {
    const assetsWww = path.join(projectDir, 'app', 'src', 'main', 'assets', 'www');
    await fs.ensureDir(assetsWww);
    await fs.copy(webDir, assetsWww, { overwrite: true });
    // If entry point is in a subfolder, copy it to root level as well
    if (config.indexSubDir) {
      const subSrc = path.join(assetsWww, config.indexSubDir);
      const indexHtmlSrc = path.join(subSrc, 'index.html');
      const indexHtmlDst = path.join(assetsWww, 'index.html');
      if (!await fs.pathExists(indexHtmlDst) && await fs.pathExists(indexHtmlSrc)) {
        await fs.copy(subSrc, assetsWww, { overwrite: false });
      }
    }
  }

  // Copy custom icon if provided
  if (config.iconFilePath && await fs.pathExists(config.iconFilePath)) {
    await copyIcon(config.iconFilePath, projectDir);
  }

  // Zip the project
  await zipProject(projectDir, path.join(buildDir, 'project.zip'));

  return projectDir;
}

// ─── generateSources ─────────────────────────────────────────────────────────
async function generateSources(projectDir, javaDir, config) {
  const vars = buildTemplateVars(config);

  // Files that contain template variables (relative to projectDir)
  const textFiles = [
    'settings.gradle',
    'app/build.gradle',
    'app/src/main/AndroidManifest.xml',
    'app/src/main/res/values/strings.xml',
    'app/src/main/res/values/colors.xml',
    'app/src/main/res/values/themes.xml',
  ];

  for (const rel of textFiles) {
    const filePath = path.join(projectDir, rel);
    if (await fs.pathExists(filePath)) {
      let content = await fs.readFile(filePath, 'utf8');
      content = applyVars(content, vars);
      await fs.writeFile(filePath, content, 'utf8');
    }
  }

  // Generate MainActivity.java
  const mainActivityContent = generateMainActivity(config, vars);
  await fs.writeFile(path.join(javaDir, 'MainActivity.java'), mainActivityContent, 'utf8');

  // Remove the placeholder java directory if it exists
  const placeholderJava = path.join(projectDir, 'app', 'src', 'main', 'java', 'PACKAGE_PLACEHOLDER');
  await fs.remove(placeholderJava).catch(() => {});
}

function buildTemplateVars(config) {
  return {
    '{{APP_NAME}}':      config.appName,
    '{{PACKAGE_NAME}}':  config.packageName,
    '{{VERSION_NAME}}':  config.versionName,
    '{{VERSION_CODE}}':  String(config.versionCode),
    '{{MIN_SDK}}':       String(config.minSdk),
    '{{TARGET_SDK}}':    '34',
    '{{COMPILE_SDK}}':   '34',
    '{{STATUS_BAR_COLOR}}': config.statusBarColor,
    '{{ORIENTATION}}':   config.orientation,
  };
}

function applyVars(content, vars) {
  let result = content;
  for (const [key, value] of Object.entries(vars)) {
    result = result.split(key).join(value);
  }
  return result;
}

// ─── generateMainActivity ─────────────────────────────────────────────────────
function generateMainActivity(config, vars) {
  const pkg        = config.packageName;
  const loadType   = config.loadType || 'local';
  const loadUrl    = config.loadUrl  || 'file:///android_asset/www/index.html';
  const enableZoom = config.enableZoom !== false;
  const fullscreen = config.fullscreen === true;
  const extLinks   = config.allowExternalLinks === true;

  const loadUrlLine = loadType === 'url'
    ? `webView.loadUrl("${loadUrl}");`
    : `webView.loadUrl("file:///android_asset/www/index.html");`;

  const fullscreenImports = fullscreen ? `
import android.view.View;
import android.view.WindowManager;` : '';

  const fullscreenCode = fullscreen ? `
        getWindow().setFlags(
            WindowManager.LayoutParams.FLAG_FULLSCREEN,
            WindowManager.LayoutParams.FLAG_FULLSCREEN
        );
        getWindow().getDecorView().setSystemUiVisibility(
            View.SYSTEM_UI_FLAG_FULLSCREEN
                | View.SYSTEM_UI_FLAG_HIDE_NAVIGATION
                | View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY
        );` : '';

  const extLinksImport = extLinks ? `
import android.content.Intent;
import android.net.Uri;` : '';

  const webViewClientClass = extLinks ? `
        webView.setWebViewClient(new WebViewClient() {
            @Override
            public boolean shouldOverrideUrlLoading(WebView view, String url) {
                if (url != null && (url.startsWith("http://") || url.startsWith("https://"))) {
                    boolean isSameHost = Uri.parse(url).getHost() != null
                        && Uri.parse(url).getHost().equals(Uri.parse("${loadUrl}").getHost());
                    if (!isSameHost) {
                        Intent intent = new Intent(Intent.ACTION_VIEW, Uri.parse(url));
                        startActivity(intent);
                        return true;
                    }
                }
                return false;
            }
        });` : `
        webView.setWebViewClient(new WebViewClient());`;

  return `package ${pkg};

import android.app.Activity;
import android.os.Bundle;
import android.webkit.WebSettings;
import android.webkit.WebView;
import android.webkit.WebViewClient;${fullscreenImports}${extLinksImport}

public class MainActivity extends Activity {

    private WebView webView;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);${fullscreenCode}
        setContentView(R.layout.activity_main);

        webView = findViewById(R.id.webview);

        WebSettings settings = webView.getSettings();
        settings.setJavaScriptEnabled(true);
        settings.setDomStorageEnabled(true);
        settings.setAllowFileAccess(true);
        settings.setAllowContentAccess(true);
        settings.setDatabaseEnabled(true);
        settings.setSupportZoom(${enableZoom});
        settings.setBuiltInZoomControls(${enableZoom});
        settings.setDisplayZoomControls(false);
        settings.setLoadWithOverviewMode(true);
        settings.setUseWideViewPort(true);
        settings.setMixedContentMode(WebSettings.MIXED_CONTENT_ALWAYS_ALLOW);
${webViewClientClass}

        if (savedInstanceState != null) {
            webView.restoreState(savedInstanceState);
        } else {
            ${loadUrlLine}
        }
    }

    @Override
    protected void onSaveInstanceState(Bundle outState) {
        super.onSaveInstanceState(outState);
        webView.saveState(outState);
    }

    @Override
    public void onBackPressed() {
        if (webView.canGoBack()) {
            webView.goBack();
        } else {
            super.onBackPressed();
        }
    }
}
`;
}

// ─── copyIcon ────────────────────────────────────────────────────────────────
async function copyIcon(iconSrc, projectDir) {
  const densities = [
    { name: 'mipmap-mdpi',    size: 48  },
    { name: 'mipmap-hdpi',    size: 72  },
    { name: 'mipmap-xhdpi',   size: 96  },
    { name: 'mipmap-xxhdpi',  size: 144 },
    { name: 'mipmap-xxxhdpi', size: 192 },
  ];
  for (const d of densities) {
    const destDir = path.join(projectDir, 'app', 'src', 'main', 'res', d.name);
    await fs.ensureDir(destDir);
    await fs.copy(iconSrc, path.join(destDir, 'ic_launcher.png'));
  }
}

// ─── zipProject ──────────────────────────────────────────────────────────────
function zipProject(projectDir, outputPath) {
  return new Promise((resolve, reject) => {
    const output  = fs.createWriteStream(outputPath);
    const archive = archiver('zip', { zlib: { level: 6 } });

    output.on('close', resolve);
    archive.on('error', reject);

    archive.pipe(output);
    archive.directory(projectDir, path.basename(projectDir));
    archive.finalize();
  });
}

// ─── build (Gradle) ──────────────────────────────────────────────────────────
/**
 * Attempts to build the APK with Gradle.
 * On success: copies APK to buildsDir/<buildId>/<appName>.apk
 * On failure: just returns projectZipPath
 */
async function build(projectDir, buildId, onProgress, buildsDir) {
  const buildDir = path.join(buildsDir, buildId);
  const projectZipPath = path.join(buildDir, 'project.zip');

  // Detect Gradle command
  const gradleCmd = await detectGradle(projectDir);

  if (!gradleCmd) {
    onProgress('⚠️  Gradle not found. Skipping APK build – project ZIP is ready for Android Studio.');
    return { apkPath: null, projectZipPath };
  }

  onProgress(`🔨 Running: ${gradleCmd} assembleDebug`);

  try {
    const { stdout, stderr } = await execAsync(
      `${gradleCmd} assembleDebug`,
      {
        cwd: projectDir,
        timeout: 10 * 60 * 1000, // 10 minutes
        env: { ...process.env, JAVA_OPTS: '-Xmx1g' }
      }
    );

    // Log Gradle output (trimmed)
    const lines = (stdout + '\n' + stderr)
      .split('\n')
      .map(l => l.trim())
      .filter(l => l.length > 0 && !l.startsWith('Note:'));

    lines.forEach(l => onProgress(l));

    // Find the output APK
    const apkSrc = findBuiltApk(projectDir);
    if (!apkSrc) throw new Error('Gradle build succeeded but no APK was found in build outputs.');

    const apkDest = path.join(buildDir, 'app-debug.apk');
    await fs.copy(apkSrc, apkDest);
    onProgress(`📱 APK saved: app-debug.apk`);

    return { apkPath: apkDest, projectZipPath };

  } catch (err) {
    const errMsg = (err.stderr || err.stdout || err.message || '').substring(0, 600);
    onProgress(`⚠️  Gradle build failed: ${errMsg}`);
    onProgress('📦 Project ZIP is still available for manual build in Android Studio.');
    return { apkPath: null, projectZipPath };
  }
}

function findBuiltApk(projectDir) {
  const candidates = [
    path.join(projectDir, 'app', 'build', 'outputs', 'apk', 'debug', 'app-debug.apk'),
    path.join(projectDir, 'app', 'build', 'outputs', 'apk', 'release', 'app-release-unsigned.apk'),
  ];
  for (const c of candidates) {
    if (fs.existsSync(c)) return c;
  }
  return null;
}

async function detectGradle(projectDir) {
  const isWin = process.platform === 'win32';

  // 1. Gradle wrapper in project
  const wrapperCmd = isWin
    ? path.join(projectDir, 'gradlew.bat')
    : path.join(projectDir, 'gradlew');

  if (await fs.pathExists(wrapperCmd)) {
    if (!isWin) {
      try { await execAsync(`chmod +x "${wrapperCmd}"`); } catch (_) { /**/ }
    }
    return isWin ? `"${wrapperCmd}"` : `"${wrapperCmd}"`;
  }

  // 2. System Gradle
  try {
    await execAsync('gradle --version', { timeout: 5000 });
    return 'gradle';
  } catch (_) {
    return null;
  }
}

module.exports = { createProject, build };
